### 1. 任务状态管理
我们将使用一个字典来存储任务的状态，包括任务ID、状态（如“未执行”、“执行中”、“已完成”、“失败”）和执行时间。

```python
import time

class TaskManager:
    def __init__(self):
        self.tasks = {}

    def add_task(self, task_id):
        self.tasks[task_id] = {
            'status': '未执行',
            'execution_time': None
        }

    def execute_task(self, task_id):
        if task_id not in self.tasks:
            print(f"任务 {task_id} 不存在")
            return

        if self.tasks[task_id]['status'] == '执行中':
            print(f"任务 {task_id} 正在执行")
            return

        self.tasks[task_id]['status'] = '执行中'
        self.tasks[task_id]['execution_time'] = time.time()
        print(f"任务 {task_id} 开始执行")

        # 模拟任务执行
        if self.tasks[task_id]['status'] == '执行中':
            self.tasks[task_id]['status'] = '已完成'
            print(f"任务 {task_id} 执行完成")
        else:
            self.tasks[task_id]['status'] = '失败'
            print(f"任务 {task_id} 执行失败")

    def get_task_status(self, task_id):
        if task_id not in self.tasks:
            return "任务不存在"
        return self.tasks[task_id]['status']

    def get_task_execution_time(self, task_id):
        if task_id not in self.tasks:
            return "任务不存在"
        return self.tasks[task_id]['execution_time']
